const f = $input.first().json.body || {};
const email = (f.email || '').toLowerCase();
const domain = email.split('@')[1] || '';
const freeDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com'];
const isBusinessEmail = domain !== '' && !freeDomains.includes(domain);
const budgetPoints = { 'Under $1k': 5, '$1k-$5k': 15, '$5k-$20k': 25, '$20k+': 35 }[f.budget] ?? 0;
const sizePoints = { '1-10': 5, '11-50': 10, '51-200': 15, '200+': 20 }[f.companySize] ?? 0;
const timelinePoints = { 'This month': 20, '1-3 months': 15, '3+ months': 5 }[f.timeline] ?? 0;
const businessPoints = isBusinessEmail ? 10 : 0;
const score = budgetPoints + sizePoints + timelinePoints + businessPoints;
const tier = score >= 70 ? 'Hot' : score >= 40 ? 'Warm' : 'Cold';
return [{ json: { submittedAt: new Date().toISOString(), name: f.name, email: f.email, company: f.company, companySize: f.companySize, budget: f.budget, timeline: f.timeline, message: f.message || '', businessEmail: isBusinessEmail, score, tier } }];

